SELECT ?name ?item ?sv (GROUP_CONCAT(DISTINCT ?svAlt; separator=" | ") AS ?svAlts) (GROUP_CONCAT(DISTINCT CONCAT(STR(?amt), " ", STR(?unitLabel)); separator=" | ") AS ?conv) WHERE {
  VALUES ?name { "inch"@en "foot"@en "yard"@en "mile"@en "nautical mile"@en "fathom"@en "chain"@en "furlong"@en
    "square foot"@en "acre"@en "square mile"@en "cubic foot"@en "US gallon"@en "imperial gallon"@en "US liquid pint"@en "imperial pint"@en
    "US fluid ounce"@en "imperial fluid ounce"@en "barrel"@en "grain"@en "ounce"@en "troy ounce"@en "pound"@en "stone"@en
    "short ton"@en "long ton"@en "miles per hour"@en "mile per hour"@en "knot"@en "pound-force"@en "pound per square inch"@en "pound-force per square inch"@en
    "horsepower"@en "mechanical horsepower"@en "British thermal unit"@en "degree Fahrenheit"@en "pint"@en "gallon"@en "fluid ounce"@en "avoirdupois pound"@en "avoirdupois ounce"@en "oil barrel"@en }
  ?item rdfs:label ?name .
  ?item wdt:P2370 [] .
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item skos:altLabel ?svAlt FILTER(LANG(?svAlt) = "sv") }
  OPTIONAL { ?item p:P2370/psv:P2370 [ wikibase:quantityAmount ?amt ; wikibase:quantityUnit ?u ] . ?u rdfs:label ?unitLabel FILTER(LANG(?unitLabel) = "en") }
} GROUP BY ?name ?item ?sv ORDER BY ?name

SELECT ?item ?en ?sv (GROUP_CONCAT(DISTINCT ?svAlt; separator=" | ") AS ?svAlts) (GROUP_CONCAT(DISTINCT ?sym; separator=" | ") AS ?syms) (GROUP_CONCAT(DISTINCT CONCAT(STR(?amt), " ", STR(?unitLabel)); separator=" | ") AS ?conv) WHERE {
  VALUES ?item { wd:Q218593 wd:Q3710 wd:Q482798 wd:Q253276 wd:Q93318 wd:Q61794388 wd:Q6502423 wd:Q61793679 wd:Q552299
    wd:Q61794946 wd:Q494083 wd:Q857027 wd:Q81292 wd:Q232291 wd:Q1545979 wd:Q23925413 wd:Q23925410 wd:Q32750621 wd:Q11123
    wd:Q32750759 wd:Q69878540 wd:Q89187604 wd:Q693944 wd:Q48013 wd:Q1323615 wd:Q100995 wd:Q1131660 wd:Q469356 wd:Q667419
    wd:Q211256 wd:Q128822 wd:Q1194225 wd:Q626299 wd:Q2276380 wd:Q99490009 wd:Q42289 }
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item skos:altLabel ?svAlt FILTER(LANG(?svAlt) = "sv") }
  OPTIONAL { ?item wdt:P5061 ?sym }
  OPTIONAL { ?item p:P2370/psv:P2370 [ wikibase:quantityAmount ?amt ; wikibase:quantityUnit ?u ] . ?u rdfs:label ?unitLabel FILTER(LANG(?unitLabel) = "en") }
} GROUP BY ?item ?en ?sv ORDER BY ?en
